<script setup>
import { computed, onMounted, ref } from 'vue';
import { adminApi } from '@/api';
import ConfirmDialog from '@/components/common/ConfirmDialog.vue';
import { useToast } from '@/stores/toast';
import { buildGoodsReceiptPayload, filterGoodsReceipts, goodsReceiptContentUnits, goodsReceiptPreview, goodsReceiptTotal, goodsReceiptUnitOptions, hydrateGoodsReceiptLine, receiptCostWarning, receiptDateSummary, receiptGroupsByDate, resolveGoodsReceiptLine, validateGoodsReceipt } from '@/utils/inventoryOperations';
import { formatQuantity } from '@/utils/inventoryItem';

const toast = useToast();
const receipts = ref([]);
const inventoryItems = ref([]);
const loading = ref(true);
const loadError = ref('');
const saving = ref(false);
const formError = ref('');
const editingId = ref(null);
const confirmation = ref(null);
const form = ref(blankForm());
const itemById = computed(() => new Map(inventoryItems.value.map((item) => [item.inventoryItemId, item])));
const receivableItems = computed(() => inventoryItems.value.filter(item => item.active !== false && item.itemType === 'INGREDIENT').sort((a,b) => a.name.localeCompare(b.name,'vi')));
const receiptFilters = ref({ fromDate: localDate(), toDate: localDate(), status: 'ALL' });
const filteredReceipts = computed(() => filterGoodsReceipts(receipts.value, receiptFilters.value));
const receiptSummary = computed(() => receiptDateSummary(filteredReceipts.value));
const receiptGroups = computed(() => receiptGroupsByDate(filteredReceipts.value));
const itemsObject = computed(() => Object.fromEntries(inventoryItems.value.map((item) => [item.inventoryItemId, item])));
const documentTotal = computed(() => goodsReceiptTotal(form.value.items, itemsObject.value));
const summaryLines = computed(() => form.value.items.map((line) => ({ line, item: item(line), preview: preview(line) })).filter(row => row.item));

function localDateTime() { const date = new Date(); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); }
function localDate(date = new Date()) { const value=new Date(date);value.setMinutes(value.getMinutes()-value.getTimezoneOffset());return value.toISOString().slice(0,10); }
function preset(days) { const to=new Date(),from=new Date();from.setDate(from.getDate()-Math.max(0,days-1));receiptFilters.value.fromDate=localDate(from);receiptFilters.value.toDate=localDate(to); }
function dateHeading(date) { const today=localDate(),yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);if(date===today)return `Hôm nay · ${date}`;if(date===localDate(yesterday))return `Hôm qua · ${date}`;return date; }
function blankLine() { return { inventoryItemId: '', purchaseQuantity: '', purchaseUnit: '', packageQuantity: '', packageUnit: '', purchaseUnitPrice: '', legacyUnit: false }; }
function blankForm() { return { supplierName: '', invoiceNumber: '', receivedAt: localDateTime(), items: [blankLine()] }; }
function money(value) { return Number(value).toLocaleString('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }); }
function item(line) { return itemById.value.get(Number(line.inventoryItemId)); }
function preview(line) { return goodsReceiptPreview(line, item(line)); }
function unitOptions(line) { return goodsReceiptUnitOptions(item(line)?.baseUnit); }
function contentUnits(line) { return goodsReceiptContentUnits(item(line)?.baseUnit); }
function isPackaging(line) { return ['bao', 'hộp', 'khay', 'thùng', 'chai'].includes(line.purchaseUnit); }
function unitLabel(unit) { return ({ G: 'g', ML: 'ml', PIECE: 'cái' }[unit] || unit || ''); }
function displayQuantity(value, baseUnit) { const amount = Number(value); if (!Number.isFinite(amount)) return '—'; if (baseUnit === 'G' && amount >= 1000) return `${formatQuantity(amount / 1000)} kg`; if (baseUnit === 'ML' && amount >= 1000) return `${formatQuantity(amount / 1000)} L`; return `${formatQuantity(amount)} ${unitLabel(baseUnit)}`; }
function currentStock(line) { const selected = item(line); return selected ? displayQuantity(selected.onHandQuantity, selected.baseUnit) : '—'; }
function increaseDisplay(line) { const selected = item(line); const result = preview(line); if (!selected || result.baseQuantity == null) return '—'; if (!isPackaging(line)) return `${formatQuantity(line.purchaseQuantity)} ${line.purchaseUnit}`; return displayQuantity(result.baseQuantity, selected.baseUnit); }
function convertedCost(line) { const selected = item(line); const result = preview(line); if (!selected || result.baseUnitCost == null) return '—'; const multiplier = selected.baseUnit === 'G' || selected.baseUnit === 'ML' ? 1000 : 1; const label = selected.baseUnit === 'G' ? 'kg' : selected.baseUnit === 'ML' ? 'L' : 'cái'; return `${money(result.baseUnitCost * multiplier)}/${label}`; }
function conversionText(line) { const selected = item(line); const conversion = resolveGoodsReceiptLine(line, selected?.baseUnit); if (!selected || !conversion) return ''; if (isPackaging(line)) return `${formatQuantity(line.purchaseQuantity)} ${line.purchaseUnit} × ${formatQuantity(line.packageQuantity)} ${line.packageUnit} = ${displayQuantity(preview(line).baseQuantity, selected.baseUnit)}`; return `Quy đổi tự động: 1 ${line.purchaseUnit} = ${formatQuantity(conversion.conversionFactor)} ${unitLabel(selected.baseUnit)} trong hệ thống`; }
function priceDisplay(value) { const digits = String(value ?? '').replace(/\D/g, ''); return digits ? Number(digits).toLocaleString('vi-VN') : ''; }
function setPrice(line, event) { line.purchaseUnitPrice = event.target.value.replace(/\D/g, ''); event.target.value = priceDisplay(line.purchaseUnitPrice); }
function chooseItem(line) { const selected = item(line); const first = goodsReceiptUnitOptions(selected?.baseUnit)[0]; Object.assign(line, { purchaseUnit: first?.value || '', packageQuantity: '', packageUnit: '', legacyUnit: false }); }
function chooseUnit(line) { line.packageQuantity = ''; line.packageUnit = isPackaging(line) ? contentUnits(line)[0]?.value || '' : ''; line.legacyUnit = false; }
async function load() { loading.value = true; loadError.value = ''; try { const [list, items] = await Promise.all([adminApi.getGoodsReceipts(), adminApi.getInventoryItems()]); receipts.value = Array.isArray(list) ? list : []; inventoryItems.value = Array.isArray(items) ? items : []; } catch (error) { loadError.value = error.message || 'Không thể tải phiếu nhập'; } finally { loading.value = false; } }
function addLine() { form.value.items.push(blankLine()); }
function removeLine(index) { if (form.value.items.length > 1) form.value.items.splice(index, 1); }
function resetForm() { editingId.value = null; form.value = blankForm(); formError.value = ''; }
async function editReceipt(receipt) { formError.value = ''; try { const detail = await adminApi.getGoodsReceipt(receipt.goodsReceiptId); editingId.value = detail.goodsReceiptId; form.value = { supplierName: detail.supplierName === 'Không khai báo' ? '' : detail.supplierName, invoiceNumber: detail.invoiceNumber || '', receivedAt: String(detail.receivedAt).slice(0, 16), items: detail.items.map((line) => hydrateGoodsReceiptLine(line, itemById.value.get(Number(line.inventoryItemId)))) }; document.querySelector('#receipt-form')?.scrollIntoView({ behavior: 'smooth' }); } catch (error) { formError.value = error.message || 'Không thể mở phiếu nhập'; } }
async function save(review = false) { const errors = validateGoodsReceipt(form.value, itemsObject.value); if (Object.keys(errors).length) { formError.value = Object.values(errors)[0]; return; } saving.value = true; formError.value = ''; try { const payload = buildGoodsReceiptPayload(form.value, itemsObject.value); const saved = editingId.value ? await adminApi.updateGoodsReceipt(editingId.value, payload) : await adminApi.createGoodsReceipt(payload); editingId.value = saved.goodsReceiptId; if (review) { confirmation.value = { kind: 'approve', receipt: saved }; await load(); return; } toast.success('Đã lưu phiếu nhập nháp'); resetForm(); await load(); } catch (error) { formError.value = error.message || 'Không thể lưu phiếu nhập'; } finally { saving.value = false; } }
function requestConfirmation(kind, receipt) { confirmation.value = { kind, receipt }; }
async function approve(receipt) { saving.value = true; try { await adminApi.approveGoodsReceipt(receipt.goodsReceiptId); toast.success('Đã duyệt phiếu nhập'); resetForm(); await load(); } catch (error) { loadError.value = error.message || 'Không thể duyệt phiếu nhập'; } finally { saving.value = false; confirmation.value = null; } }
async function remove(receipt) { saving.value = true; try { await adminApi.deleteGoodsReceipt(receipt.goodsReceiptId); if (editingId.value === receipt.goodsReceiptId) resetForm(); await load(); } catch (error) { loadError.value = error.message || 'Không thể xóa phiếu nhập'; } finally { saving.value = false; confirmation.value = null; } }
function confirmAction() { const { kind, receipt } = confirmation.value; return kind === 'approve' ? approve(receipt) : remove(receipt); }
function approvalMessage(receipt) { const rows = (receipt?.items || []).map(line => { const selected = itemById.value.get(Number(line.inventoryItemId)); return `${selected?.name || `#${line.inventoryItemId}`}: +${displayQuantity(line.baseQuantity, selected?.baseUnit)}`; }); const warnings = form.value.items.map(line => receiptCostWarning(line, item(line))).filter(Boolean); return `Kho sẽ tăng: ${rows.join('; ')}. Tổng giá trị: ${money((receipt?.items || []).reduce((sum, line) => sum + Number(line.lineTotal || 0), 0))}. Sau khi duyệt, số lượng và giá vốn sẽ được cập nhật; phiếu không thể sửa lại.${warnings.length ? ' Có đơn giá cao bất thường cần kiểm tra.' : ''}`; }
onMounted(load);
</script>

<template>
  <main class="ops-page">
    <header class="page-heading"><div><p class="eyebrow">Nhập hàng</p><h1>Ghi nhận nguyên liệu vừa nhận</h1><p>Chọn mặt hàng, số lượng, đơn vị mua và giá. Hệ thống tự quy đổi sang đơn vị kho.</p></div><button class="btn btn-outline" :disabled="loading" @click="load">Làm mới</button></header>
    <section id="receipt-form" class="panel">
      <div class="section-heading"><h2>{{ editingId ? `Sửa phiếu #${editingId}` : 'Tạo phiếu nhập' }}</h2><button v-if="editingId" class="btn btn-sm btn-outline" type="button" @click="resetForm">Tạo phiếu mới</button></div>
      <form @submit.prevent="save(false)">
        <fieldset><legend><span>1</span> Thông tin phiếu</legend><div class="form-grid"><label>Nhà cung cấp <small>(không bắt buộc)</small><input v-model="form.supplierName" class="form-input" maxlength="150" placeholder="Nhập tên nếu có" /></label><label>Số hóa đơn <small>(không bắt buộc)</small><input v-model="form.invoiceNumber" class="form-input" maxlength="100" placeholder="HD-250826" /></label><label>Thời gian nhận<input v-model="form.receivedAt" class="form-input" type="datetime-local" required /></label></div></fieldset>
        <fieldset><legend><span>2</span> Nguyên liệu nhận được</legend><article v-for="(line,index) in form.items" :key="index" class="ingredient-card">
          <header><strong>Nguyên liệu {{ String(index + 1).padStart(2, '0') }}</strong><button class="btn btn-sm btn-outline" type="button" :disabled="form.items.length === 1" :aria-label="`Xóa nguyên liệu ${index + 1}`" @click="removeLine(index)">Xóa</button></header>
          <label class="item-field">Nguyên liệu<select v-model="line.inventoryItemId" class="form-select" required @change="chooseItem(line)"><option value="">Chọn nguyên liệu</option><option v-for="candidate in receivableItems" :key="candidate.inventoryItemId" :value="String(candidate.inventoryItemId)">{{ candidate.inventoryCode }} · {{ candidate.name }}</option></select></label>
          <p class="current-stock">Tồn hiện tại: <strong>{{ currentStock(line) }}</strong></p>
          <div class="purchase-fields"><label>Số lượng nhận<input v-model="line.purchaseQuantity" class="form-input" type="number" min="0.0001" step="0.0001" required /></label><label>Đơn vị mua<select v-model="line.purchaseUnit" class="form-select" required @change="chooseUnit(line)"><option value="">Chọn đơn vị</option><option v-if="line.legacyUnit" :value="line.purchaseUnit">Đơn vị cũ: {{ line.purchaseUnit }}</option><option v-for="unit in unitOptions(line)" :key="unit.value" :value="unit.value">{{ unit.value }}</option></select></label><label>Giá mỗi {{ line.purchaseUnit || 'đơn vị mua' }}<div class="money-input"><input :value="priceDisplay(line.purchaseUnitPrice)" class="form-input" inputmode="numeric" required @input="setPrice(line,$event)" /><span>₫ / {{ line.purchaseUnit || 'đơn vị' }}</span></div></label></div>
          <div v-if="isPackaging(line)" class="package-fields"><label>1 {{ line.purchaseUnit }} chứa<input v-model="line.packageQuantity" class="form-input" type="number" min="0.0001" step="0.0001" required /></label><label>Đơn vị bên trong<select v-model="line.packageUnit" class="form-select" required><option v-for="unit in contentUnits(line)" :key="unit.value" :value="unit.value">{{ unit.value }}</option></select></label></div>
          <p v-if="conversionText(line)" class="conversion">{{ conversionText(line) }}</p>
          <p v-if="receiptCostWarning(line,item(line))" class="price-warning" role="status"><strong>Đơn giá cao bất thường.</strong> {{ receiptCostWarning(line,item(line)) }}</p>
          <dl class="preview" aria-live="polite"><div><dt>Kho sẽ tăng</dt><dd>+{{ increaseDisplay(line) }}</dd></div><div><dt>Thành tiền</dt><dd>{{ preview(line).lineTotal == null ? '—' : money(preview(line).lineTotal) }}</dd></div><div><dt>Giá vốn quy đổi</dt><dd>{{ convertedCost(line) }}</dd></div></dl>
        </article><button class="btn btn-sm btn-outline add-line" type="button" @click="addLine">+ Thêm nguyên liệu</button></fieldset>
        <fieldset class="review-fieldset"><legend><span>3</span> Tóm tắt phiếu</legend><p><strong>{{ summaryLines.length }} nguyên liệu</strong></p><ul><li v-for="row in summaryLines" :key="row.line.inventoryItemId"><span>{{ row.item.name }} · +{{ increaseDisplay(row.line) }}</span><strong>{{ row.preview.lineTotal == null ? '—' : money(row.preview.lineTotal) }}</strong></li></ul><div class="document-total" aria-live="polite"><span>Tổng giá trị nhập</span><strong>{{ money(documentTotal) }}</strong></div></fieldset>
        <p v-if="formError" class="error-box" role="alert">{{ formError }}</p><div class="actions"><button class="btn btn-outline" type="submit" :disabled="saving">{{ saving ? 'Đang lưu...' : 'Lưu nháp' }}</button><button class="btn btn-primary" type="button" :disabled="saving" @click="save(true)">Kiểm tra & duyệt</button></div>
      </form>
    </section>
    <section class="panel receipt-history"><div class="section-heading"><div><h2>Phiếu nhập theo ngày</h2><p class="muted">Tổng giá trị chỉ tính phiếu đã duyệt và thực sự tăng kho.</p></div></div><div class="date-presets"><button type="button" @click="preset(1)">Hôm nay</button><button type="button" @click="preset(7)">7 ngày</button><button type="button" @click="preset(30)">30 ngày</button></div><div class="receipt-filters"><label>Từ ngày<input v-model="receiptFilters.fromDate" class="form-input" type="date" :max="receiptFilters.toDate" /></label><label>Đến ngày<input v-model="receiptFilters.toDate" class="form-input" type="date" :min="receiptFilters.fromDate" /></label><label>Trạng thái<select v-model="receiptFilters.status" class="form-select"><option value="ALL">Tất cả</option><option value="DRAFT">Nháp</option><option value="APPROVED">Đã duyệt</option></select></label></div><section class="receipt-kpis" aria-label="Tổng hợp phiếu nhập"><article><span>Tổng phiếu</span><strong>{{ receiptSummary.receiptCount }}</strong></article><article><span>Đã duyệt</span><strong>{{ receiptSummary.approvedCount }}</strong></article><article><span>Loại nguyên liệu</span><strong>{{ receiptSummary.ingredientCount }}</strong></article><article><span>Tổng giá trị nhập</span><strong>{{ money(receiptSummary.approvedValue) }}</strong></article></section><div v-if="loading" class="state" role="status">Đang tải...</div><div v-else-if="loadError" class="state error" role="alert">{{ loadError }} <button class="btn btn-sm btn-outline" @click="load">Thử lại</button></div><div v-else-if="!receiptGroups.length" class="state">Không có phiếu nhập trong khoảng ngày này.</div><section v-for="group in receiptGroups" v-else :key="group.date" class="receipt-day"><h3>{{ dateHeading(group.date) }}</h3><div class="table-wrapper"><table class="table"><thead><tr><th>Mã</th><th>Nhà cung cấp</th><th>Hóa đơn</th><th>Thời gian nhận</th><th>Nguyên liệu</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="receipt in group.receipts" :key="receipt.goodsReceiptId" :class="{ locked: receipt.status !== 'DRAFT' }"><td data-label="Mã">#{{ receipt.goodsReceiptId }}</td><td data-label="Nhà cung cấp"><strong>{{ receipt.supplierName }}</strong></td><td data-label="Hóa đơn">{{ receipt.invoiceNumber || '—' }}</td><td data-label="Thời gian nhận">{{ String(receipt.receivedAt).slice(11,16) }}</td><td data-label="Nguyên liệu">{{ receipt.items.length }}</td><td data-label="Trạng thái"><span class="badge" :class="receipt.status === 'DRAFT' ? 'badge-warning' : 'badge-success'">{{ receipt.status === 'DRAFT' ? 'Nháp · cần kiểm tra' : 'Đã duyệt' }}</span></td><td data-label="Thao tác"><div v-if="receipt.status === 'DRAFT'" class="row-actions"><button class="btn btn-sm btn-outline" @click="editReceipt(receipt)">Sửa</button><button class="btn btn-sm btn-primary" @click="requestConfirmation('approve', receipt)">Duyệt</button><button class="btn btn-sm btn-outline" @click="requestConfirmation('delete', receipt)">Xóa</button></div><span v-else class="locked-label"><i class="bi bi-lock" aria-hidden="true"></i> Phiếu đã khóa</span></td></tr></tbody></table></div></section></section>
    <ConfirmDialog :open="Boolean(confirmation)" :busy="saving" :title="confirmation?.kind === 'approve' ? `Duyệt phiếu nhập #${confirmation.receipt.goodsReceiptId}?` : `Xóa phiếu nháp #${confirmation?.receipt.goodsReceiptId}?`" :message="confirmation?.kind === 'approve' ? approvalMessage(confirmation.receipt) : 'Phiếu nháp sẽ bị xóa và không ảnh hưởng tồn kho.'" :confirm-label="confirmation?.kind === 'approve' ? 'Duyệt phiếu' : 'Xóa phiếu'" @confirm="confirmAction" @cancel="confirmation = null" />
  </main>
</template>

<style scoped>
.ops-page{display:grid;gap:20px;min-width:0;overflow-x:hidden}.page-heading,.section-heading,.actions,.row-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.page-heading h1{margin:2px 0;font-size:28px}.page-heading p{margin:0;color:var(--text-mid)}.eyebrow{color:var(--role-admin)!important;font-size:11px!important;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.panel{min-width:0;background:#fff;border:1px solid var(--border-light);border-radius:14px;padding:20px;display:grid;gap:14px}.panel h2{margin:0;font-size:18px}form,fieldset,.form-grid,.line-card,label{min-width:0}form{display:grid;gap:16px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}label{display:grid;gap:6px;color:var(--text-mid);font-size:12px;font-weight:700}label :is(input,select){width:100%;min-width:0;box-sizing:border-box}fieldset{border:1px solid var(--border-light);border-radius:12px;padding:16px;display:grid;gap:12px}legend{font-size:14px;font-weight:800;padding:0 8px}legend span{display:inline-grid;place-items:center;width:26px;height:26px;margin-right:6px;border-radius:50%;background:var(--primary);color:#fff}.line-card{display:grid;grid-template-columns:2fr repeat(4,minmax(0,1fr)) auto;gap:10px;align-items:end;padding:12px;background:var(--surface);border-radius:10px}.conversion,.preview{grid-column:1/-2;margin:0;overflow-wrap:anywhere}.conversion{font-size:13px}.preview{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--text-mid)}.review-fieldset{background:#fffaf6}.review-fieldset p{margin:0;color:var(--text-mid)}.document-total{display:flex;justify-content:space-between;gap:12px;font-size:16px}.document-total strong{font-size:22px}.actions{justify-content:flex-end}.error-box{color:#b91c1c;background:#fef2f2;padding:10px;border-radius:8px}.state{padding:34px;text-align:center;color:var(--text-mid)}.error{color:#b91c1c}.table-wrapper{overflow-x:auto}.table{min-width:900px}.locked{background:var(--surface);color:var(--text-mid)}.locked-label,.muted{color:var(--text-mid)}.ops-page :is(button,input,select):focus-visible{outline:3px solid var(--primary);outline-offset:2px}.ops-page :is(button,input,select){min-height:40px}@media(max-width:900px){.form-grid{grid-template-columns:1fr}.line-card{grid-template-columns:repeat(2,minmax(0,1fr))}.line-card label:first-child,.conversion,.preview{grid-column:1/-1}.table-wrapper{overflow:visible}.table{min-width:0}.table thead{display:none}.table,.table tbody,.table tr,.table td{display:block;width:100%;box-sizing:border-box}.table tr{padding:14px;border-bottom:1px solid var(--border-light)}.table td{display:grid;grid-template-columns:minmax(90px,100px) minmax(0,1fr);gap:10px;padding:6px 0;border:0}.table td:before{content:attr(data-label);color:var(--text-mid);font-size:12px}}@media(max-width:600px){.panel{padding:14px}.page-heading{align-items:flex-start;flex-direction:column}.line-card{grid-template-columns:minmax(0,1fr)}.line-card>*{grid-column:1!important}.row-actions{justify-content:flex-start}}
.ops-page{grid-template-columns:minmax(0,1fr);overflow-x:visible}.ingredient-card{display:grid;gap:14px;min-width:0;padding:18px;border:1px solid var(--border-light);border-radius:12px;background:#fff}.ingredient-card>header{display:flex;align-items:center;justify-content:space-between;gap:12px;text-transform:uppercase;font-size:12px;letter-spacing:.06em}.item-field{max-width:720px}.current-stock{margin:-6px 0 0;color:var(--text-mid);font-size:13px}.purchase-fields{display:grid;grid-template-columns:minmax(120px,.7fr) minmax(150px,.8fr) minmax(220px,1.4fr);gap:12px}.money-input{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px}.money-input span{white-space:nowrap}.package-fields{display:grid;grid-template-columns:minmax(140px,220px) minmax(140px,220px);align-items:end;gap:10px}.ingredient-card .conversion{grid-column:auto;margin:0;padding:10px 12px;border-radius:8px;background:var(--surface);font-size:13px}.price-warning{margin:0;padding:10px 12px;border:1px solid #fed7aa;border-radius:8px;background:#fff7ed;color:#9a3412;font-size:13px}.ingredient-card .preview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-column:auto;gap:10px;margin:0;padding-top:12px;border-top:1px solid var(--border-light)}.preview div{display:grid;gap:4px}.preview dt{color:var(--text-mid);font-size:12px}.preview dd{margin:0;font-size:16px;font-weight:800}.add-line{justify-self:start}.review-fieldset ul{display:grid;gap:8px;margin:0;padding:0;list-style:none}.review-fieldset li{display:flex;justify-content:space-between;gap:12px;padding-bottom:8px;border-bottom:1px dashed var(--border-light)}
